import json

response = '''
{
  "status": "ok",
  "results": [
    { "name": "Ann Arbor", "lat": 42.2808, "lng": -83.7430 }
  ]
}'''

js = json.loads(response)

place = None
if js['status'] != 'ok':
    place = None
else:
    place = js['results'][0]

if place is None:
    print('status: error')
else:
    print('status: ok')
    print('lat:', place['lat'])
    print('lng:', place['lng'])

import json

payload = '''
{
  "status": "OK",
  "results": [
    { "formatted_address": "Ann Arbor, MI, USA", "lat": 42.2808, "lng": -83.7430 },
    { "formatted_address": "Ypsilanti, MI, USA", "lat": 42.2412, "lng": -83.6142 }
  ]
}'''

js = json.loads(payload)

if js['status'] != 'OK':
    js = None

if js is None:
    print('status: error')
else:
    print('results:', len(js['results']))
    first = js['results'][0]
    print('lat: %s' % first['lat'])
    print('lng: %s' % first['lng'])
